"""
Utilities for plotting 3d Gaussians.

These utilities are used for calculating ellipsoid principal axes from a covariance as well as the
intersection of an ellipsoid with a plane.
The code has been generated by Claude Fable 5 and Gemini 3; the results have been visually inspected for correctness.
"""

import numpy as np


def ellipsoid_axes_from_cov(cov: np.ndarray, nstd: float = 1.0) -> tuple[np.ndarray, np.ndarray]:
    """
    Compute ellipsoid half-axes from a covariance matrix via eigendecomposition.

    :param cov: The covariance.
    :param nstd: Scaling in terms of standard deviation.
    :return: Radii and the rotation matrix.
    """
    eigvals, R = np.linalg.eigh(cov)  # eigh: symmetric, sorted ascending
    if np.any(eigvals <= 0.0):
        msg = "covariance matrix must be positive definite"
        raise ValueError(msg)
    if np.linalg.det(R) < 0.0:  # keep a right-handed frame
        R[:, 0] *= -1.0
    radii = nstd * np.sqrt(eigvals)
    return radii, R


def conjugate_to_principal_axes(g1: np.ndarray, g2: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """
    Convert conjugate half-axes of an ellipse into its principal half-axes.

    For a pair of conjugate half-axes g1, g2 of the ellipse ``p(t) = center + g1 cos t + g2 sin t``
    the extrema of ``|p(t) - center|^2`` occur at t0 with ``tan(2 t0) = 2 (g1.g2) / (|g1|^2 - |g2|^2)``,
    which yields the (orthogonal) principal half-axes f1, f2 (analytic form of Rytz's axis construction).

    :param g1: First conjugate half-axis.
    :param g2: Second conjugate half-axis.
    :return: Principal half-axes.
    """
    g1 = np.asarray(g1, float)
    g2 = np.asarray(g2, float)
    t0 = 0.5 * np.arctan2(2.0 * (g1 @ g2), (g1 @ g1) - (g2 @ g2))
    f1 = g1 * np.cos(t0) + g2 * np.sin(t0)
    f2 = -g1 * np.sin(t0) + g2 * np.cos(t0)
    if np.linalg.norm(f1) < np.linalg.norm(f2):  # f1 = major, f2 = minor
        f1, f2 = f2, -f1
    return f1, f2


def ellipse_points(
    center: np.ndarray,
    f1: np.ndarray,
    f2: np.ndarray,
    n_points: int = 200,
) -> np.ndarray:
    """
    Extract the points for a 3D ellipse given by its center and half-axis vectors ``f1``, ``f2``.

    :param center: Origin of the ellipse.
    :param f1: First half-axis.
    :param f2: Second half-axis.
    :param n_points: Number of points to use when drawing using points.
    :return: Edge points of the ellipse.
    """
    t = np.linspace(0.0, 2.0 * np.pi, n_points)
    return center[:, None] + np.cos(t) * f1[:, None] + np.sin(t) * f2[:, None]


def ellipsoid_points(
    center: np.ndarray,
    radii: np.ndarray,
    R: np.ndarray,
    n_u: int = 40,
    n_v: int = 30,
) -> np.ndarray:
    """
    Plot the ellipsoid defined by its center and a 3x3 covariance matrix.

    :param center: Origin of the covariance.
    :param radii: Radii of the half-axes.
    :param R: The rotation matrix.
    :param n_u: Number of points to plot along the azimuth coordinate.
    :param n_v: Number of points to plot along the polar coordinate.
    :return: Points on the ellipsoid.
    """
    # unit sphere ...
    u = np.linspace(0.0, 2.0 * np.pi, n_u)  # azimuth
    v = np.linspace(0.0, np.pi, n_v)  # polar
    sphere = np.stack(
        [
            np.outer(np.cos(u), np.sin(v)),
            np.outer(np.sin(u), np.sin(v)),
            np.outer(np.ones_like(u), np.cos(v)),
        ]
    )

    # ... scaled by the radii, rotated by R and shifted to the center
    return np.einsum("ij,juv->iuv", R * radii, sphere) + center[:, None, None]


def ellipsoid_plane_intersection(
    center: np.ndarray,
    cov: np.ndarray,
    n: np.ndarray,
    d: float,
    nstd: float = 1.0,
) -> tuple[np.ndarray, np.ndarray, np.ndarray] | tuple[None, None, None]:
    """
    Compute the intersection ellipse of an ellipsoid and a plane.

    The ellipsoid is ``(x - center)^T cov^-1 (x - center) = nstd^2`` and the
    plane is ``n_hat . (x - center) = d`` with the unit normal ``n_hat = n / |n|``, i.e. the plane
    is offset by the distance ``d`` from the ellipsoid center along the normal.
    Returns ``(ell_center, f1, f2)`` where ``f1``, ``f2`` are the orthogonal
    principal half-axes of the ellipse ``(|f1| >= |f2|)``, so that
    ``p(t) = ell_center + f1 cos t + f2 sin t,   t in [0, 2 pi)``.
    Returns (None, None, None) if plane and ellipsoid do not intersect.

    Method: with ``T = R diag(radii)`` from the eigendecomposition of cov,
    ``x = center + T u`` maps the unit sphere ``|u| = 1`` onto the ellipsoid.
    The plane becomes ``m . u = d`` with ``m = T^T n_hat``,
    which cuts the unit sphere in a circle; mapping that circle back
    through ``T`` yields the ellipse.

    :param center: Center of the ellipsoid.
    :param cov: Covariance.
    :param n: Normal vector of plane, does not need to be normalized.
    :param d: Offset of plane from the ellipsoid center along the normal vector.
    :param nstd: Scaling in terms of standard deviation.
    :return: Center, f1 and f2 of the resulting ellipse.
    """
    radii, R = ellipsoid_axes_from_cov(cov, nstd)
    T = R * radii  # = R @ diag(radii)

    n_hat = n / np.linalg.norm(n)
    m = T.T @ n_hat  # transformed plane normal
    m2 = m @ m
    if d * d >= m2:  # no (real) intersection
        return None, None, None

    c0 = (d / m2) * m  # circle center on unit sphere
    r = np.sqrt(1.0 - d * d / m2)  # circle radius

    # orthonormal basis {e1, e2} of the plane through origin with normal m
    m_hat = m / np.linalg.norm(m)
    helper = np.array([1.0, 0.0, 0.0])
    if abs(m_hat @ helper) > 0.9:
        helper = np.array([0.0, 1.0, 0.0])
    e1 = np.cross(m_hat, helper)
    e1 /= np.linalg.norm(e1)
    e2 = np.cross(m_hat, e1)

    # map circle back to the ellipsoid: x(t) = center + T (c0 + r cos t e1 + ...)
    ell_center = center + T @ c0
    g1 = T @ (r * e1)  # conjugate half-axes (in general
    g2 = T @ (r * e2)  # not orthogonal after mapping)
    f1, f2 = conjugate_to_principal_axes(g1, g2)
    return ell_center, f1, f2


def ellipsoid_plane_intersection_points(
    center: np.ndarray,
    cov: np.ndarray,
    n: np.ndarray,
    d: float = 0.0,
    nstd: float = 1.0,
    n_points: int = 200,
) -> np.ndarray:
    """
    Extract the points for the intersection ellipse of an ellipsoid and a plane.

    :param center: Center of the ellipsoid.
    :param cov: Covariance.
    :param n: Normal vector of plane, does not need to be normalized.
    :param d: Offset of plane from the ellipsoid center along the normal vector.
    :param nstd: Scaling in terms of standard deviation.
    :param n_points: Number of points to use when drawing using points.
    :return: Edge points of the ellipse.
    """
    ell_center, f1, f2 = ellipsoid_plane_intersection(center, cov, n, d, nstd)
    if ell_center is not None and f1 is not None and f2 is not None:
        return ellipse_points(ell_center, f1, f2, n_points)
    return np.array([])


def find_optimal_trajectory_offset(traj_A: np.ndarray, traj_B: np.ndarray) -> tuple:
    """
    Finds the single integer shift for traj_B that minimizes Euclidean distance to traj_A.

    :param traj_A: (N, dim) First trajectory.
    :param traj_B: (N, dim) First trajectory.
    :return: Minimal mean distance and offset of B wrt. A.
    """
    best_offset = 0
    min_mean_dist = float("inf")

    # Test all shifts
    for shift in range(len(traj_A)):
        seg_B = traj_B if shift == 0 else np.vstack((traj_B[shift:], traj_B[:shift]))

        mean_dist = np.mean(np.linalg.norm(traj_A - seg_B, axis=1))

        if mean_dist < min_mean_dist:
            min_mean_dist = mean_dist
            best_offset = shift

    return best_offset, min_mean_dist


def merge_shapes(ellipses: list[np.ndarray], *, add_sides: bool = True) -> list[np.ndarray]:
    """
    Merge flat 2D shapes, creating a 3D "tube" along their outline.

    :param ellipses: Points of the flat 2D shapes. Each shapes has to contain the same number of points.
    :param add_sides: Add start / end.
    :return: The vertices of the 3D shape as triangle mesh.
    """
    faces = [ellipses[0], ellipses[-1]] if add_sides else []
    old_offs = 0
    for i in range(len(ellipses) - 1):
        s1 = ellipses[i]  # First layer
        s2 = ellipses[i + 1]  # Last layer

        n = len(s1)  # Number of points in one flat shape
        offs, _ = find_optimal_trajectory_offset(s1, s2)  # Offset between two layers

        # Create & append vertice
        for j in range(n):
            p1 = s1[(j + old_offs) % n]
            p2 = s1[(j + 1 + old_offs) % n]
            p3 = s2[(j + 1 + offs + old_offs) % n]
            p4 = s2[(j + offs + old_offs) % n]
            faces.append(np.array([p1, p2, p3]))
            faces.append(np.array([p1, p3, p4]))

        old_offs += offs
    return faces
